import { useCallback, useEffect, useMemo, useState } from "react";

interface PanelProps { projectId: string }
interface Artifact { id:number; kind:string; format:string; name:string; size_bytes:number; storage_file_id?:string }
interface Check { code:string; severity:"error"|"warning"; message:string; object_ids?:string[] }
interface Validation { status:string; errors:number; warnings:number; report:{ checks:Check[] } }
interface Revision { id:number; number:number; source_sha256:string; definition:Definition }
interface Design { id:number; name:string; status:string; current_revision_id:number; current_revision?:Revision; validation?:Validation; artifacts?:Artifact[]; updated_at:string }
interface Point { x_nm:number; y_nm:number }
interface Pad { id:string;pin_id:string;shape:"rect"|"roundrect"|"circle"|"oval";x_nm:number;y_nm:number;width_nm:number;height_nm:number;drill_nm?:number;layers:string[] }
interface Definition {
  schema:string; name?:string;
  board:{ width_nm:number; height_nm:number; layers:{id:string;kind:string;order:number}[] };
  rules:{ min_clearance_nm:number; min_trace_width_nm:number; min_edge_clearance_nm:number;min_drill_nm?:number;min_annular_ring_nm?:number };
  components:{ id:string;designator:string;name:string;value?:string;mpn?:string;footprint?:string;position:{x_nm:number;y_nm:number;rotation_udeg:number;side:string};body?:{width_nm:number;height_nm:number};pins?:unknown[];pads?:Pad[] }[];
  nets:{id:string;name:string;nodes?:unknown[]}[];
  traces:{id:string;net_id:string;layer:string;width_nm:number;points:Point[]}[];
  vias:{id:string;net_id:string;x_nm:number;y_nm:number;diameter_nm:number;drill_nm:number;from_layer:string;to_layer:string}[];
  zones?:{id:string;net_id:string;layer:string;clearance_nm?:number;polygon:Point[]}[];
  keepouts?:{id:string;kind:string;layer?:string;owner_id?:string;polygon:Point[]}[];
  differential_pairs?:{id:string;positive_net_id:string;negative_net_id:string;target_ohms?:number;gap_nm:number;gap_tolerance_nm?:number;max_skew_nm:number}[];
  net_classes?:{id:string;net_ids:string[];trace_width_nm?:number;clearance_nm?:number;via_diameter_nm?:number;via_drill_nm?:number;priority?:number}[];
  simulation?:unknown;
}
interface RoutePlan { status:string;grid_nm:number;routed_nets:string[];skipped_nets?:string[];failures?:{net_id:string;message:string}[];operations:{type:string;trace?:Definition["traces"][number];via?:Definition["vias"][number]}[];metrics:{requested_nets:number;routed_nets:number;skipped_nets:number;trace_count:number;via_count:number;total_length_nm:number;visited_nodes:number} }
interface SimulationResult { status:string;duration_us:number;step_us:number;samples:number;final_voltage_v:Record<string,number>;final_digital:Record<string,string>;waveforms:{probe_id:string;net_id:string;kind:string;unit:string;points:{time_us:number;value:number;digital?:string}[]}[];device_states?:Record<string,unknown>[];warnings?:string[] }
interface FirmwareResult { status:string;runtime:string;board:string;duration_us:number;serial_baud?:number;serial_output:string[];pin_states:Record<string,string>;i2c_transactions:{time_us:number;address:number;bytes:number[];status:string}[];warnings?:string[] }

const API="/api/apps/pcb/api";
const TEMPLATE:Definition={schema:"apteva-pcb/v1",name:"Controller board",board:{width_nm:50000000,height_nm:30000000,layers:[{id:"F.Cu",kind:"copper",order:0},{id:"B.Cu",kind:"copper",order:1},{id:"F.SilkS",kind:"silkscreen",order:2}]},rules:{min_clearance_nm:200000,min_trace_width_nm:200000,min_edge_clearance_nm:250000,min_drill_nm:200000,min_annular_ring_nm:125000},components:[{id:"u1",designator:"U1",name:"Microcontroller",value:"RP2040",mpn:"RP2040",footprint:"QFN-56",position:{x_nm:25000000,y_nm:15000000,rotation_udeg:0,side:"front"},body:{width_nm:7000000,height_nm:7000000},pins:[{id:"1",number:"1",name:"IO0",electrical_type:"bidirectional",pad:"1"}],pads:[{id:"1",pin_id:"1",shape:"roundrect",x_nm:-3500000,y_nm:0,width_nm:900000,height_nm:400000,layers:["F.Cu"]}]},{id:"j1",designator:"J1",name:"Connector",value:"USB-C",footprint:"USB-C-16P",position:{x_nm:5000000,y_nm:15000000,rotation_udeg:0,side:"front"},body:{width_nm:8000000,height_nm:9000000},pins:[{id:"1",number:"1",name:"D+",electrical_type:"bidirectional",pad:"1"}],pads:[{id:"1",pin_id:"1",shape:"roundrect",x_nm:4000000,y_nm:0,width_nm:900000,height_nm:400000,layers:["F.Cu"]}]}],nets:[{id:"usb-dp",name:"USB_D+",nodes:[{component_id:"u1",pin_id:"1"},{component_id:"j1",pin_id:"1"}]}],traces:[{id:"usb-dp-1",net_id:"usb-dp",layer:"F.Cu",width_nm:250000,points:[{x_nm:9000000,y_nm:15000000},{x_nm:21500000,y_nm:15000000}]}],vias:[],zones:[],keepouts:[],differential_pairs:[]};
function url(path:string,projectId:string){return `${API}${path}${path.includes("?")?"&":"?"}project_id=${encodeURIComponent(projectId)}`}
async function request(path:string,projectId:string,init?:RequestInit){const response=await fetch(url(path,projectId),{credentials:"same-origin",...init,headers:{"Content-Type":"application/json",...(init?.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||response.statusText);return body}
const mm=(nm:number)=>nm/1e6;
const DEFAULT_FIRMWARE=`#include <Wire.h>

void setup() {
  Serial.begin(115200);
  Wire.begin();
  Wire.beginTransmission(0x70);
  Wire.write(0x7C);
  Wire.endTransmission();
  pinMode(8, OUTPUT);
}

void loop() {
  float temperature = sensor.readTemperature();
  float humidity = sensor.readHumidity();
  Serial.print("Temperature: ");
  Serial.println(temperature);
  Serial.print("Humidity: ");
  Serial.println(humidity);
  digitalWrite(8, HIGH);
  delay(1000);
}`;

export default function PCBPanel({projectId}:PanelProps){
  const [designs,setDesigns]=useState<Design[]>([]),[selectedId,setSelectedId]=useState<number|null>(null),[design,setDesign]=useState<Design|null>(null);
  const [source,setSource]=useState(JSON.stringify(TEMPLATE,null,2)),[newName,setNewName]=useState("Controller board"),[note,setNote]=useState("");
  const [tab,setTab]=useState<"board"|"route"|"simulate"|"firmware"|"source">("board"),[busy,setBusy]=useState(""),[error,setError]=useState("");
  const [routePlan,setRoutePlan]=useState<RoutePlan|null>(null),[simulation,setSimulation]=useState<SimulationResult|null>(null),[firmware,setFirmware]=useState<FirmwareResult|null>(null),[firmwareSource,setFirmwareSource]=useState(DEFAULT_FIRMWARE);
  const parsed=useMemo(()=>{try{return JSON.parse(source) as Definition}catch{return null}},[source]);
  const loadDesigns=useCallback(async()=>{const body=await request("/designs?status=all",projectId);setDesigns(body.designs||[]);if(!selectedId&&body.designs?.length)setSelectedId(body.designs[0].id)},[projectId,selectedId]);
  const loadDesign=useCallback(async(id:number)=>{const body=await request(`/designs/${id}`,projectId);setDesign(body.design);setSource(JSON.stringify(body.design.current_revision?.definition||TEMPLATE,null,2))},[projectId]);
  useEffect(()=>{loadDesigns().catch(e=>setError(e.message))},[loadDesigns]);useEffect(()=>{if(selectedId)loadDesign(selectedId).catch(e=>setError(e.message))},[selectedId,loadDesign]);
  async function run(label:string,fn:()=>Promise<void>){setBusy(label);setError("");try{await fn()}catch(e){setError((e as Error).message)}finally{setBusy("")}}
  function create(){if(!parsed)return setError("The native PCB JSON is not valid.");run("Creating",async()=>{const body=await request("/designs",projectId,{method:"POST",body:JSON.stringify({name:newName,definition:parsed,note:"Initial native board"})});await loadDesigns();setSelectedId(body.design.id)})}
  function save(){if(!design||!parsed)return setError("Select a design and fix the source JSON first.");run("Saving revision",async()=>{await request(`/designs/${design.id}/revisions`,projectId,{method:"POST",body:JSON.stringify({expected_parent_id:design.current_revision_id,definition:parsed,note})});setNote("");await loadDesign(design.id);await loadDesigns()})}
  function action(name:string,label:string){if(!design)return;run(label,async()=>{await request(`/designs/${design.id}/${name}`,projectId,{method:"POST",body:"{}"});await loadDesign(design.id)})}
  function suggestRoute(){if(!design)return;run("Analyzing routes",async()=>{const body=await request(`/designs/${design.id}/route-suggest`,projectId,{method:"POST",body:JSON.stringify({options:{grid_nm:500000,layers:["F.Cu","B.Cu"]}})});setRoutePlan(body.plan);setTab("route")})}
  function applyRoute(){if(!design||!routePlan)return;run("Applying route revision",async()=>{await request(`/designs/${design.id}/route-apply`,projectId,{method:"POST",body:JSON.stringify({options:{grid_nm:routePlan.grid_nm,layers:["F.Cu","B.Cu"]},note:"PCB Studio 0.3 native autoroute"})});setRoutePlan(null);await loadDesign(design.id);await loadDesigns();setTab("board")})}
  function runSimulation(){if(!design)return;run("Running simulation",async()=>{const body=await request(`/designs/${design.id}/simulate`,projectId,{method:"POST",body:JSON.stringify({options:{duration_us:10000,step_us:100}})});setSimulation(body.result);await loadDesign(design.id);setTab("simulate")})}
  function runFirmware(){if(!design)return;run("Running virtual firmware",async()=>{const body=await request(`/designs/${design.id}/firmware`,projectId,{method:"POST",body:JSON.stringify({options:{source:firmwareSource,language:"arduino",iterations:2}})});setFirmware(body.result);await loadDesign(design.id);setTab("firmware")})}
  const validation=design?.validation,artifacts=design?.artifacts||[];
  return <div className="pcb-root">
    <header className="pcb-header"><div className="pcb-logo"><PCBMark/></div><div className="pcb-title"><h1>PCB Studio</h1><p>Native electronics design · route · simulate · fabricate</p></div><span className="engine-pill"><i/>Apteva PCB 0.3</span><span className="grow"/><div className="action-group"><button onClick={suggestRoute} disabled={!design||!!busy}>Autoroute</button><button onClick={runSimulation} disabled={!design||!!busy}>Simulate</button><button onClick={runFirmware} disabled={!design||!!busy}>Run firmware</button><button onClick={()=>action("validate","Validating")} disabled={!design||!!busy}>Validate</button><button onClick={()=>action("manufacturing","Building fabrication files")} disabled={!design||!!busy}>Fabrication</button></div><button className="primary" onClick={()=>action("release","Creating release")} disabled={!design||!!busy}>Create release</button></header>
    {busy&&<div className="progress"/>}{error&&<div className="error">{error}</div>}
    <div className="pcb-grid">
      <aside className="library"><Label>Boards</Label>{designs.map(d=><button className="design-item" data-active={selectedId===d.id} onClick={()=>setSelectedId(d.id)} key={d.id}><strong>{d.name}</strong><small>{d.status} · r{d.id===design?.id?design.current_revision?.number:"—"}</small></button>)}{!designs.length&&<p className="muted">No boards yet.</p>}<div className="new"><Label>New native board</Label><input value={newName} onChange={e=>setNewName(e.target.value)}/><button className="primary wide" disabled={!parsed||!newName.trim()||!!busy} onClick={create}>Create from editor</button></div></aside>
      <main className="workspace"><div className="tabs"><button data-active={tab==="board"} onClick={()=>setTab("board")}>Layout</button><button data-active={tab==="route"} onClick={()=>setTab("route")}>Route</button><button data-active={tab==="simulate"} onClick={()=>setTab("simulate")}>Simulate</button><button data-active={tab==="firmware"} onClick={()=>setTab("firmware")}>Firmware</button><button data-active={tab==="source"} onClick={()=>setTab("source")}>Source</button><span className="grow"/>{design?.current_revision&&<code>revision {design.current_revision.number} · {design.current_revision.source_sha256.slice(0,10)}</code>}</div>{tab==="board"?<BoardCanvas definition={parsed||TEMPLATE}/>:tab==="route"?<RouteLab definition={parsed||TEMPLATE} plan={routePlan} onAnalyze={suggestRoute} onApply={applyRoute} disabled={!design||!!busy}/>:tab==="simulate"?<SimulationLab result={simulation} onRun={runSimulation} disabled={!design||!!busy}/>:tab==="firmware"?<FirmwareLab source={firmwareSource} setSource={setFirmwareSource} result={firmware} onRun={runFirmware} disabled={!design||!!busy}/>:<textarea spellCheck={false} value={source} onChange={e=>setSource(e.target.value)}/>}</main>
      <aside className="inspector"><Section title="Revision"><textarea className="note" placeholder="What changed?" value={note} onChange={e=>setNote(e.target.value)}/><button className="primary wide" onClick={save} disabled={!design||!parsed||!!busy}>Save immutable revision</button></Section><Section title="Native graph"><Row label="Board" value={parsed?`${mm(parsed.board.width_nm)} × ${mm(parsed.board.height_nm)} mm`:"—"}/><Row label="Layers / net classes" value={`${parsed?.board.layers.length||0} / ${parsed?.net_classes?.length||0}`}/><Row label="Components / pads" value={`${parsed?.components.length||0} / ${parsed?.components.reduce((n,c)=>n+(c.pads?.length||0),0)||0}`}/><Row label="Nets" value={String(parsed?.nets.length||0)}/><Row label="Traces / vias" value={`${parsed?.traces.length||0} / ${parsed?.vias.length||0}`}/><Row label="Zones / keepouts" value={`${parsed?.zones?.length||0} / ${parsed?.keepouts?.length||0}`}/><Row label="Differential pairs" value={String(parsed?.differential_pairs?.length||0)}/></Section><Section title="Validation"><div className={`status ${validation?.status||"idle"}`}>● {validation?.status||"not run"}{validation&&` · ${validation.errors} errors · ${validation.warnings} warnings`}</div>{validation?.report.checks.slice(0,12).map((c,i)=><div className="check" key={i} data-severity={c.severity}><b>{c.severity==="error"?"×":"!"}</b><span>{c.message}<small>{c.code}</small></span></div>)}</Section><Section title="Artifacts">{artifacts.map(a=><a className="artifact" key={a.id} href={url(`/artifacts/${a.id}/content`,projectId)}><b>{a.kind==="manufacturing"?"fab":a.kind==="simulation"?"sim":a.kind==="firmware"?"mcu":a.format}</b><span>{a.name}</span><small>{a.storage_file_id?"Storage":"local"} · {Math.max(1,Math.round(a.size_bytes/1024))}K</small></a>)}{!artifacts.length&&<p className="muted">Previews, simulations, firmware runs, fabrication files, and releases appear here and in Storage.</p>}</Section></aside>
    </div><style>{styles}{labStyles}</style>
  </div>
}

function RouteLab({definition,plan,onAnalyze,onApply,disabled}:{definition:Definition;plan:RoutePlan|null;onAnalyze:()=>void;onApply:()=>void;disabled:boolean}){
  const preview=useMemo(()=>{const next=JSON.parse(JSON.stringify(definition)) as Definition;if(plan){for(const op of plan.operations){if(op.type==="trace.add"&&op.trace)next.traces.push(op.trace);if(op.type==="via.add"&&op.via)next.vias.push(op.via)}}return next},[definition,plan]);
  return <div className="lab route-lab"><div className="lab-toolbar"><div><small>Deterministic native router</small><strong>{plan?`${plan.status} · ${plan.metrics.routed_nets} routed`:"Analyze the current immutable revision"}</strong></div><span className="grow"/><button onClick={onAnalyze} disabled={disabled}>Analyze all nets</button><button className="primary" onClick={onApply} disabled={disabled||!plan||plan.status==="failed"||!plan.operations.length}>Apply route revision</button></div><div className="route-summary">{plan?<><Metric label="Grid" value={`${mm(plan.grid_nm)} mm`}/><Metric label="New traces" value={String(plan.metrics.trace_count)}/><Metric label="New vias" value={String(plan.metrics.via_count)}/><Metric label="Length" value={`${Math.round(plan.metrics.total_length_nm/1e6)} mm`}/><Metric label="Search" value={`${plan.metrics.visited_nodes} nodes`}/></>:<p className="muted">Routing proposals are reviewable typed operations. Manual traces remain untouched unless optimization is explicitly requested.</p>}</div>{plan?.failures?.map(f=><div className="route-failure" key={f.net_id}><b>{f.net_id}</b><span>{f.message}</span></div>)}<div className="lab-canvas"><BoardCanvas definition={preview}/></div></div>
}

function SimulationLab({result,onRun,disabled}:{result:SimulationResult|null;onRun:()=>void;disabled:boolean}){
  const rails=result?Object.entries(result.final_voltage_v).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,8):[];
  return <div className="lab simulation-lab"><div className="lab-toolbar"><div><small>Native electrical lab</small><strong>{result?`${result.samples} samples · ${result.duration_us/1000} ms`:`DC + transient RC + digital events`}</strong></div><span className="grow"/><button className="primary" onClick={onRun} disabled={disabled}>Run simulation</button></div>{!result?<div className="empty-lab"><b>Probe the board before fabrication</b><p>Saved sources and probes are read from the native revision. Results and waveforms are persisted through Storage.</p></div>:<><div className="rail-grid">{rails.map(([net,value])=><div className="rail" key={net}><small>{net}</small><b>{value.toFixed(3)} V</b><span data-state={result.final_digital[net]}>{result.final_digital[net]}</span></div>)}</div><div className="wave-grid">{result.waveforms.slice(0,6).map(w=><Waveform key={w.probe_id} waveform={w}/>)}</div>{result.warnings?.map(w=><div className="route-failure" key={w}>{w}</div>)}</>}</div>
}

function Waveform({waveform:w}:{waveform:SimulationResult["waveforms"][number]}){const width=300,height=74,values=w.points.map(p=>p.value),max=Math.max(...values,1),min=Math.min(...values,0),range=Math.max(.001,max-min),path=w.points.map((p,i)=>`${i?"L":"M"}${(i/Math.max(1,w.points.length-1))*width},${height-8-((p.value-min)/range)*(height-20)}`).join(" ");return <div className="wave"><div><b>{w.probe_id}</b><span>{w.net_id} · {w.unit}</span></div><svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none"><path className="wave-gridline" d={`M0 ${height-8}H${width}M0 12H${width}`}/><path className="wave-line" d={path}/></svg></div>}

function FirmwareLab({source,setSource,result,onRun,disabled}:{source:string;setSource:(value:string)=>void;result:FirmwareResult|null;onRun:()=>void;disabled:boolean}){return <div className="lab firmware-lab"><div className="lab-toolbar"><div><small>Arduino-compatible virtual hardware</small><strong>{result?`${result.board} · ${result.runtime}`:"GPIO · Serial · I²C · virtual sensors"}</strong></div><span className="grow"/><button className="primary" onClick={onRun} disabled={disabled||!source.trim()}>Run sketch</button></div><div className="firmware-grid"><textarea className="firmware-source" spellCheck={false} value={source} onChange={e=>setSource(e.target.value)}/><div className="console"><div className="console-title"><b>Serial monitor</b><span>{result?.serial_baud||"—"} baud</span></div><pre>{result?.serial_output.join("\n")||"Run the sketch to open the virtual serial stream."}</pre>{result&&<div className="io-summary"><Metric label="Runtime" value={`${result.duration_us/1000} ms`}/><Metric label="GPIO high" value={String(Object.values(result.pin_states).filter(v=>v==="high").length)}/><Metric label="I²C transactions" value={String(result.i2c_transactions.length)}/><Metric label="I²C status" value={result.i2c_transactions.every(t=>t.status==="ack")?"ACK":"NACK"}/></div>}</div></div></div>}

function Metric({label,value}:{label:string;value:string}){return <div className="metric"><small>{label}</small><b>{value}</b></div>}

function BoardCanvas({definition:d}:{definition:Definition}){
  const w=mm(d.board.width_nm),h=mm(d.board.height_nm),[front,setFront]=useState(true),[back,setBack]=useState(true),[zones,setZones]=useState(true),[keepouts,setKeepouts]=useState(true),[zoom,setZoom]=useState(1),[selected,setSelected]=useState<string>("");
  const netNames=useMemo(()=>Object.fromEntries(d.nets.map(n=>[n.id,n.name])),[d.nets]);
  const pts=(p:Point[])=>p.map(v=>`${mm(v.x_nm)},${mm(v.y_nm)}`).join(" ");
  const layerVisible=(layer:string)=>layer==="F.Cu"?front:layer==="B.Cu"?back:true;
  const selectedComponent=d.components.find(c=>c.id===selected);
  return <div className="viewport">
    <div className="board-meta"><small>Native board</small><b>{w} × {h} mm</b><span>{d.components.reduce((n,c)=>n+(c.pads?.length||0),0)} pads · {d.traces.length} traces · {d.zones?.length||0} zones</span></div>
    <div className="view-tools"><button data-active={front} onClick={()=>setFront(!front)}><i className="front"/>Top</button><button data-active={back} onClick={()=>setBack(!back)}><i className="back"/>Bottom</button><button data-active={zones} onClick={()=>setZones(!zones)}>Zones</button><button data-active={keepouts} onClick={()=>setKeepouts(!keepouts)}>Keepouts</button><button onClick={()=>setZoom(Math.max(.65,zoom-.15))}>−</button><code>{Math.round(zoom*100)}%</code><button onClick={()=>setZoom(Math.min(2.2,zoom+.15))}>+</button></div>
    <svg aria-label="Native PCB layout" style={{transform:`scale(${zoom})`}} viewBox={`-4 -4 ${w+8} ${h+8}`}>
      <defs><linearGradient id="pcb-fill" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#21170f"/><stop offset="1" stopColor="#130e0a"/></linearGradient><pattern id="pcb-grid" width="2" height="2" patternUnits="userSpaceOnUse"><path d="M2 0H0V2" fill="none" stroke="#d0ccc8" strokeOpacity=".055" strokeWidth=".04"/></pattern><pattern id="ko" width="1.4" height="1.4" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line y2="1.4" stroke="#fbbf24" strokeOpacity=".7" strokeWidth=".18"/></pattern></defs>
      <rect className="board" width={w} height={h} rx="1"/><rect width={w} height={h} rx="1" fill="url(#pcb-grid)"/>
      {zones&&(d.zones||[]).filter(z=>layerVisible(z.layer)).map(z=><polygon className="zone" key={z.id} points={pts(z.polygon)} data-layer={z.layer}><title>{netNames[z.net_id]} zone · {z.layer}</title></polygon>)}
      {keepouts&&(d.keepouts||[]).map(k=><polygon className="keepout" key={k.id} points={pts(k.polygon)}><title>{k.kind} keepout</title></polygon>)}
      {d.traces.filter(t=>layerVisible(t.layer)).map(t=><g key={t.id}><polyline points={pts(t.points)} fill="none" stroke="#1a0b04" strokeOpacity=".75" strokeWidth={mm(t.width_nm)+.16} strokeLinecap="round" strokeLinejoin="round"/><polyline className="trace" data-layer={t.layer} points={pts(t.points)} fill="none" strokeWidth={mm(t.width_nm)} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={t.layer==="B.Cu"?".55 .22":undefined}><title>{netNames[t.net_id]} · {t.layer} · {mm(t.width_nm)} mm</title></polyline></g>)}
      {d.vias.map(v=><g key={v.id}><circle cx={mm(v.x_nm)} cy={mm(v.y_nm)} r={mm(v.diameter_nm)/2} fill="#d9b45b" stroke="#5d3f12" strokeWidth=".08"/><circle cx={mm(v.x_nm)} cy={mm(v.y_nm)} r={mm(v.drill_nm)/2} fill="#1a0b04"/><title>{netNames[v.net_id]} via · drill {mm(v.drill_nm)} mm</title></g>)}
      {d.components.map(c=>{const body=c.body||{width_nm:3000000,height_nm:2000000};return <g className="footprint" data-selected={selected===c.id} key={c.id} onClick={()=>setSelected(selected===c.id?"":c.id)} transform={`translate(${mm(c.position.x_nm)} ${mm(c.position.y_nm)}) rotate(${c.position.rotation_udeg/1e6})`}><rect className="component" x={-mm(body.width_nm)/2} y={-mm(body.height_nm)/2} width={mm(body.width_nm)} height={mm(body.height_nm)} rx=".25"/>{(c.pads||[]).filter(p=>p.layers.some(layerVisible)).map(p=>p.shape==="circle"?<circle className="pad" data-layer={p.layers.includes("F.Cu")?"F.Cu":"B.Cu"} key={p.id} cx={mm(p.x_nm)} cy={mm(p.y_nm)} r={mm(Math.min(p.width_nm,p.height_nm))/2}><title>{c.designator} pad {p.id} · pin {p.pin_id}</title></circle>:<rect className="pad" data-layer={p.layers.includes("F.Cu")?"F.Cu":"B.Cu"} key={p.id} x={mm(p.x_nm-p.width_nm/2)} y={mm(p.y_nm-p.height_nm/2)} width={mm(p.width_nm)} height={mm(p.height_nm)} rx={p.shape==="rect"?0:mm(Math.min(p.width_nm,p.height_nm))/4}><title>{c.designator} pad {p.id} · pin {p.pin_id}</title></rect>)}{(c.pads||[]).filter(p=>p.drill_nm).map(p=><circle className="drill" key={`${p.id}-drill`} cx={mm(p.x_nm)} cy={mm(p.y_nm)} r={mm(p.drill_nm||0)/2}/>)}<text y={-mm(body.height_nm)/2-.45} textAnchor="middle">{c.designator}</text><text className="value" y={mm(body.height_nm)/2+.62} textAnchor="middle">{c.value||c.name}</text><title>{c.designator} · {c.name} · {c.footprint}</title></g>})}
      <g className="dimensions"><path d={`M0 ${h+1.2}v1M${w} ${h+1.2}v1M0 ${h+1.7}H${w}`}/><text x={w/2} y={h+2.8} textAnchor="middle">{w} mm</text></g>
    </svg>
    {selectedComponent&&<div className="selection"><b>{selectedComponent.designator}</b><span>{selectedComponent.value||selectedComponent.name}</span><small>{selectedComponent.footprint} · {selectedComponent.pads?.length||0} pads · {selectedComponent.position.side}</small></div>}
    <div className="legend"><span><i className="front"/>F.Cu</span><span><i className="back"/>B.Cu</span><span><i className="pad-dot"/>pads</span><span><i className="keepout-dot"/>keepout</span></div>
  </div>
}
function Label({children}:{children:React.ReactNode}){return <div className="label">{children}</div>}
function Section({title,children}:{title:string;children:React.ReactNode}){return <section><Label>{title}</Label>{children}</section>}
function Row({label,value}:{label:string;value:string}){return <div className="row"><span>{label}</span><b>{value}</b></div>}
function PCBMark(){return <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="3.5" width="17" height="17" rx="3"/><circle cx="8" cy="8" r="1.25"/><circle cx="16" cy="16" r="1.25"/><path d="M9.25 8h3.1l2.15 2.15v4.6M8 9.25V16h6.75"/></svg>}

